package app.dailycare;
import org.junit.Test;
import static org.junit.Assert.*;
import org.json.*;
import java.util.*;

public class ReminderPlanTest {
    long at(String date,int hour,int minute){Calendar c=Calendar.getInstance();c.clear();String[] d=date.split("-");c.set(Integer.parseInt(d[0]),Integer.parseInt(d[1])-1,Integer.parseInt(d[2]),hour,minute,0);return c.getTimeInMillis();}
    JSONObject state()throws Exception{return new JSONObject("{\"settings\":{\"enabled\":true,\"timeFormat\":\"12\"},\"routines\":[],\"groups\":[],\"logs\":[],\"snoozes\":{}}");}
    JSONObject routine(String id,String name,String type,String... times)throws Exception{return new JSONObject().put("id",id).put("name",name).put("type",type).put("days",new JSONArray("[0,1,2,3,4,5,6]")).put("times",new JSONArray(times));}
    @Test public void noonMidnightAndTimePreference(){assertEquals("12:00 AM",Plan.clock("00:00","12"));assertEquals("12:00 PM",Plan.clock("12:00","12"));assertEquals("1:05 PM",Plan.clock("13:05","12"));assertEquals("23:59",Plan.clock("23:59","24"));}
    @Test public void unicodeUserTitleAndPreferredDescription()throws Exception{JSONObject s=state();s.getJSONArray("routines").put(routine("a","सुबह की दवाई","tablet","08:00"));JSONObject first=Plan.build(s,at("2026-10-28",7,0)).getJSONObject(0);assertEquals("सुबह की दवाई",first.getString("title"));assertTrue(first.getString("body").contains("8:00 AM"));s.getJSONObject("settings").put("timeFormat","24");assertTrue(Plan.build(s,at("2026-10-28",7,0)).getJSONObject(0).getString("body").contains("08:00"));}
    @Test public void oneoffTodoRepeatsAcrossDaysUntilDone()throws Exception{JSONObject s=state();s.getJSONArray("routines").put(routine("t","Call home","todo","08:00").put("dueDate","2026-10-27").put("repeatMinutes",15));JSONArray p=Plan.build(s,at("2026-10-28",9,2));assertEquals(1,p.length());assertEquals("t|2026-10-27|08:00",p.getJSONObject(0).getString("key"));assertEquals(at("2026-10-28",9,15),p.getJSONObject(0).getLong("at"));s.getJSONArray("logs").put(new JSONObject().put("key","t|2026-10-27|08:00").put("status","recorded"));assertEquals(0,Plan.build(s,at("2026-10-28",9,2)).length());}
    @Test public void medicationsNeverRepeatAndUntimedNeverAlarm()throws Exception{JSONObject s=state();s.getJSONArray("routines").put(routine("m","Medicine","tablet","08:00").put("repeatMinutes",5));s.getJSONArray("routines").put(routine("t","Untimed","todo").put("dueDate","2026-10-28").put("repeatMinutes",15));JSONArray p=Plan.build(s,at("2026-10-28",9,0));assertEquals(34,p.length());assertFalse(p.getJSONObject(0).getString("key").contains("2026-10-28"));}
    @Test public void beforeTimeAndSnoozePreserveOccurrenceIdentity()throws Exception{JSONObject s=state();s.getJSONArray("routines").put(routine("t","Leave","todo","08:00").put("dueDate","2026-10-28").put("dueMode","before").put("beforeMinutes",30).put("repeatMinutes",15));JSONObject e=Plan.build(s,at("2026-10-28",7,0)).getJSONObject(0);assertEquals(at("2026-10-28",7,30),e.getLong("at"));assertEquals("t|2026-10-28|08:00",e.getString("key"));s.getJSONObject("snoozes").put(e.getString("key"),at("2026-10-28",8,45));assertEquals(at("2026-10-28",8,45),Plan.build(s,at("2026-10-28",8,0)).getJSONObject(0).getLong("at"));assertEquals(0,s.getJSONArray("logs").length());}
    @Test public void delayedAlarmProcessesEveryPendingTimeOnceWithoutOldBacklog()throws Exception{JSONArray pending=new JSONArray();pending.put(new JSONObject().put("key","a|today|08:00").put("at",at("2026-10-28",8,0)));pending.put(new JSONObject().put("key","b|today|09:00").put("at",at("2026-10-28",9,0)));pending.put(new JSONObject().put("key","old").put("at",at("2026-10-26",9,0)));JSONObject ledger=new JSONObject();JSONArray due=Plan.due(pending,ledger,at("2026-10-28",9,30));assertEquals(2,due.length());for(int i=0;i<due.length();i++){JSONObject e=due.getJSONObject(i);ledger.put(e.getString("key")+"|"+e.getLong("at"),true);}assertEquals(0,Plan.due(pending,ledger,at("2026-10-28",9,31)).length());}
    @Test public void groupIdentityIncludesDateAndMemberKeysRemainSeparate()throws Exception{JSONObject s=state();s.getJSONArray("routines").put(routine("a","A","capsule","08:00"));s.getJSONArray("routines").put(routine("b","B","cream","08:00"));s.getJSONArray("groups").put(new JSONObject().put("id","g").put("name","Morning care").put("members",new JSONArray("[{\"routineId\":\"a\",\"time\":\"08:00\"},{\"routineId\":\"b\",\"time\":\"08:00\"}]")));JSONObject e=Plan.build(s,at("2026-10-28",7,0)).getJSONObject(0);assertEquals("g|2026-10-28|08:00",e.getString("key"));assertEquals(2,e.getJSONArray("occurrences").length());s.getJSONArray("logs").put(new JSONObject().put("key","a|2026-10-28|08:00").put("status","skipped"));assertEquals(1,Plan.build(s,at("2026-10-28",7,0)).getJSONObject(0).getJSONArray("occurrences").length());}
    @Test public void previousDaySnoozeUsesHistoricalScheduleSnapshot()throws Exception{JSONObject s=state();JSONObject old=routine("a","A","tablet","23:50");JSONObject r=routine("a","A","tablet","09:00").put("scheduleFrom","2026-10-28").put("scheduleVersions",new JSONArray().put(new JSONObject().put("from","0000-01-01").put("snapshot",old)));s.getJSONArray("routines").put(r);s.getJSONObject("snoozes").put("a|2026-10-27|23:50",at("2026-10-28",0,10));assertEquals("a|2026-10-27|23:50",Plan.build(s,at("2026-10-28",0,5)).getJSONObject(0).getString("key"));}
    @Test public void zoneChangePausesAndIndependentStateRemainsEmpty()throws Exception{JSONObject s=state();s.getJSONArray("routines").put(routine("a","A","water","08:00"));s.getJSONObject("settings").put("zone",TimeZone.getDefault().getRawOffset()==0?"Asia/Kolkata":"UTC");assertEquals(0,Plan.build(s,at("2026-10-28",7,0)).length());assertEquals(0,Plan.build(state(),at("2026-10-28",7,0)).length());}
    @Test public void refreshBeforeDelayedReceiverPreservesAlertExactlyOnce()throws Exception{JSONObject s=state();s.getJSONArray("routines").put(routine("a","A","tablet","08:00"));JSONArray pending=Plan.build(s,at("2026-10-28",7,59));JSONObject ledger=new JSONObject();JSONArray merged=Plan.mergePending(pending,Plan.build(s,at("2026-10-28",8,1)),s,ledger,at("2026-10-28",8,1));JSONArray due=Plan.due(merged,ledger,at("2026-10-28",8,5));assertEquals(1,due.length());JSONObject e=due.getJSONObject(0);ledger.put(e.getString("key")+"|"+e.getLong("at"),at("2026-10-28",8,5));assertEquals(0,Plan.due(Plan.mergePending(merged,Plan.build(s,at("2026-10-28",8,6)),s,ledger,at("2026-10-28",8,6)),ledger,at("2026-10-28",8,6)).length());}
    @Test public void completionArchiveSnoozeAndUndoDoNotResurrectPendingDose()throws Exception{JSONObject s=state();JSONObject r=routine("a","A","tablet","08:00");s.getJSONArray("routines").put(r);JSONArray pending=Plan.build(s,at("2026-10-28",7,59));long now=at("2026-10-28",8,1);s.getJSONArray("logs").put(new JSONObject().put("key","a|2026-10-28|08:00"));JSONArray cleared=Plan.mergePending(pending,Plan.build(s,now),s,new JSONObject(),now);assertEquals(0,Plan.due(cleared,new JSONObject(),now).length());s.getJSONArray("logs").getJSONObject(0).put("undone","later");assertEquals(0,Plan.due(Plan.mergePending(cleared,Plan.build(s,now),s,new JSONObject(),now),new JSONObject(),now).length());r.put("archived",true);assertEquals(0,Plan.mergePending(pending,new JSONArray(),s,new JSONObject(),now).length());r.put("archived",false);s.getJSONObject("snoozes").put("a|2026-10-28|08:00",at("2026-10-28",8,16));assertEquals(0,Plan.due(Plan.mergePending(pending,Plan.build(s,now),s,new JSONObject(),now),new JSONObject(),now).length());}
    @Test public void reportedMedicineScheduleChangeAppliesTomorrow()throws Exception{JSONObject s=state();JSONObject old=routine("a","A","tablet","08:00"),r=routine("a","A","tablet","09:00").put("scheduleFrom","2026-10-29").put("scheduleVersions",new JSONArray().put(new JSONObject().put("from","0000-01-01").put("snapshot",old)));s.getJSONArray("routines").put(r);s.getJSONArray("logs").put(new JSONObject().put("key","a|2026-10-28|08:00"));JSONArray p=Plan.build(s,at("2026-10-28",8,30));assertEquals("a|2026-10-29|09:00",p.getJSONObject(0).getString("key"));r.put("archived",true);assertEquals(0,Plan.build(s,at("2026-10-28",8,30)).length());}
    @Test public void changingOldOneoffTodoToUntimedCancelsRepeat()throws Exception{JSONObject s=state();JSONObject old=routine("t","Todo","todo","08:00").put("dueDate","2026-10-27").put("repeatMinutes",15),r=routine("t","Todo","todo").put("dueDate","2026-10-27").put("scheduleFrom","2026-10-28").put("scheduleVersions",new JSONArray().put(new JSONObject().put("from","0000-01-01").put("snapshot",old)));s.getJSONArray("routines").put(old);JSONArray pending=Plan.build(s,at("2026-10-28",8,0));s.getJSONArray("routines").put(0,r);assertEquals(0,Plan.build(s,at("2026-10-28",8,1)).length());assertEquals(0,Plan.mergePending(pending,new JSONArray(),s,new JSONObject(),at("2026-10-28",8,16)).length());}

    @Test public void delayedPendingUsesLatestTimePreferenceAndTitle()throws Exception{JSONObject s=state();JSONObject r=routine("a","Old title","tablet","13:00");s.getJSONArray("routines").put(r);JSONArray pending=Plan.build(s,at("2026-10-28",12,59));s.getJSONObject("settings").put("timeFormat","24");r.put("name","Updated title");JSONArray merged=Plan.mergePending(pending,Plan.build(s,at("2026-10-28",13,1)),s,new JSONObject(),at("2026-10-28",13,1));JSONObject entry=Plan.due(merged,new JSONObject(),at("2026-10-28",13,2)).getJSONObject(0);assertEquals("Updated title",entry.getString("title"));assertTrue(entry.getString("body").contains("13:00"));assertFalse(entry.getString("body").contains("PM"));assertEquals("a|2026-10-28|13:00",entry.getString("key"));assertEquals(at("2026-10-28",13,0),entry.getLong("at"));}
    @Test public void newlyAllowedPermissionDoesNotDeliverOldPendingBacklog()throws Exception{JSONObject s=state();s.getJSONArray("routines").put(routine("a","A","tablet","08:00","09:00"));JSONArray pending=Plan.build(s,at("2026-10-28",7,59));long now=at("2026-10-28",8,5);JSONArray granted=Plan.afterPermissionTransition(pending,false,true,now);assertEquals(0,Plan.due(Plan.mergePending(granted,Plan.build(s,now),s,new JSONObject(),now),new JSONObject(),now).length());assertEquals(1,Plan.due(Plan.mergePending(Plan.afterPermissionTransition(pending,true,true,now),Plan.build(s,now),s,new JSONObject(),now),new JSONObject(),now).length());}
    // The reminder notification (tap and full-screen intent) reuses this exact key to open
    // the occurrence or group card; the key must never drift from the occurrence identity.
    @Test public void notificationKeyCarriesExactOccurrenceIdentity()throws Exception{JSONObject s=state();s.getJSONArray("routines").put(routine("a","A","tablet","08:00"));JSONObject single=Plan.build(s,at("2026-10-28",7,0)).getJSONObject(0);assertEquals("a|2026-10-28|08:00",single.getString("key"));assertEquals(1,single.getJSONArray("occurrences").length());assertEquals("a|2026-10-28|08:00",single.getJSONArray("occurrences").getString(0));s.getJSONArray("routines").put(routine("b","B","cream","08:00"));s.getJSONArray("groups").put(new JSONObject().put("id","g").put("name","Morning care").put("members",new JSONArray("[{\"routineId\":\"a\",\"time\":\"08:00\"},{\"routineId\":\"b\",\"time\":\"08:00\"}]")));JSONObject grouped=Plan.build(s,at("2026-10-28",7,0)).getJSONObject(0);assertEquals("g|2026-10-28|08:00",grouped.getString("key"));assertEquals(2,grouped.getJSONArray("occurrences").length());assertTrue(grouped.getJSONArray("occurrences").toString().contains("a|2026-10-28|08:00"));assertTrue(grouped.getJSONArray("occurrences").toString().contains("b|2026-10-28|08:00"));}
}
